// 무엇을 어떻게 가져오나 (2026-09-06 고침)
//  🔴 전에는 전부 "캐시 우선" 이라 새 버전을 올려도 폰이 옛 것을 계속 보여줬다(사장님 "뭐가 달라진 거야? 똑같잖아").
//  코드·데이터(.html/.js/.json)는 가볍다 → **네트워크 우선**. 인터넷이 안 되면 그때 저장본을 쓴다(오프라인 유지).
//  모델·그림·소리는 무겁고 잘 안 바뀐다 → **캐시 우선**(빠르다). 파일 이름이 바뀌면 어차피 새로 받는다.
// 🔴 2026-09-08 추가: `assets/ui/` (버튼·판 테두리 그림 9장, **전부 합쳐 5KB**)도 네트워크 우선으로 옮겼다.
//    이것들이 캐시 우선이라, 새 버전을 올려도 **첫 열기에는 옛 버튼·옛 테두리가 그대로 그려졌다**
//    (13MB 를 미리 받는 동안 옛 워커가 화면을 그리기 때문). 사장님이 「모서리 문양 아직 있잖아」 하신 것이 이것이다.
//    🛑 캐시 찾기가 ignoreSearch: true 라 주소에 ?v= 를 붙여도 소용없다 — 그래서 여기 넣는 것이 유일한 해결이다.
//    5KB 라 네트워크 우선이어도 부담이 없고, 인터넷이 끊기면 아래 catch 가 저장본을 쓴다.
const FRESH = /\.(html|js|json)$|\/$|\/assets\/ui\//i;

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;                                   // 서버 시각용 HEAD 는 그대로 인터넷으로
  if (req.headers.get('cache-control') === 'no-cache') return;        // 서버 시각용 GET(오늘의 판 날짜)
  const url = new URL(req.url);
  if (url.origin !== location.origin) return;

  if (FRESH.test(url.pathname)) {
    // 네트워크 우선 — 새 것이 있으면 무조건 새 것. 안 되면 저장본
    e.respondWith(
      fetch(req, { cache: 'reload' }).then((res) => {   // 🔴 브라우저 HTTP 캐시를 건너뛴다 — GitHub Pages 의 max-age 때문에 옛 파일이 나오던 것(2026-09-07)
        if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
        return res;
      }).catch(() => caches.match(req, { ignoreSearch: true }).then((hit) => hit || Response.error()))
    );
    return;
  }
  // 캐시 우선 — 모델·그림 등 무거운 것
  e.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res && res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  })));
});
self.addEventListener('message', (e) => { if (e.data === 'skipWaiting') self.skipWaiting(); });
